						),
					`${l.reference}${ctx.pipe ? "=>" : "&"}${r.reference}`
				),
			...defineRightwardIntersections("alias", (l, r, ctx) => {
				if (r.isUnknown()) return l
				if (r.isNever()) return r
				if (r.isBasis() && !r.overlaps($ark.intrinsic.object)) {
