				if (path.length) {
					ctx.error({
						problem: uncapitalize(message),
						relativePath: path.map(k => (typeof k === "object" ? k.key : k))
					})
				} else {
					ctx.error({
						message
					})
				}
			} else {
				ctx.error({
					message
				})
