import { throwParseError } from "@ark/util"
import type { JsonSchema } from "arktype"
import {
	writeInvalidRefFormatMessage,
	writeUnresolvableRefMessage
} from "./errors.ts"

export const getRefName = (ref: string): string => {
	if (!ref.startsWith("#/$defs/")) throwParseError(writeInvalidRefFormatMessage())
	const name = ref.slice("#/$defs/".length)
	if (name.length === 0 || name.includes("/"))
		throwParseError(writeInvalidRefFormatMessage())
	return name
}

const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

export const hasObjectKeywords = (schema: JsonSchema): boolean =>
	objectKeywords.some(keyword => keyword in schema)

const rawStringDef = (schema: JsonSchema.String): string | undefined => {
	if ("pattern" in schema || "format" in schema) return
	let def = "string"
	if ("minLength" in schema) def += ` >= ${schema.minLength}`
	if ("maxLength" in schema) def += ` <= ${schema.maxLength}`
	return def
}

const rawNumberDef = (schema: JsonSchema.Numeric): string | undefined => {
	let def = "number"
	if ("multipleOf" in schema) def += ` % ${schema.multipleOf}`
	else if (schema.type === "integer") def += ".integer"
	if ("minimum" in schema) def += ` >= ${schema.minimum}`
	else if ("exclusiveMinimum" in schema) def += ` > ${schema.exclusiveMinimum}`
	if ("maximum" in schema) def += ` <= ${schema.maximum}`
	else if ("exclusiveMaximum" in schema) def += ` < ${schema.exclusiveMaximum}`
	return def
}

const rawEnumDef = (schema: JsonSchema.Enum): string | undefined => {
	if (schema.enum.length === 0) return "never"
	for (const value of schema.enum)
		if (typeof value === "object" && value !== null) return
	return schema.enum
		.map(value =>
			typeof value === "string"
				? `'${value.replaceAll("'", "\\'")}'`
				: String(value)
		)
		.join(" | ")
}

const rawObjectDef = (
	schema: JsonSchema.Object,
	defs: Record<string, JsonSchema>
): Record<string, unknown> | undefined => {
	if (
		"maxProperties" in schema ||
		"minProperties" in schema ||
		"propertyNames" in schema ||
		"dependencies" in schema ||
		"dependentRequired" in schema ||
		"dependentSchemas" in schema
	)
		return

	const result: Record<string, unknown> = {}
	const required = new Set(schema.required ?? [])

	if (schema.properties) {
		for (const [key, value] of Object.entries(schema.properties)) {
			const raw = jsonSchemaToRawDef(value, defs)
			if (raw === undefined) return
			result[required.has(key) ? key : `${key}?`] = raw
		}
	}

	if (schema.patternProperties) {
		for (const [key, value] of Object.entries(schema.patternProperties)) {
			const raw = jsonSchemaToRawDef(value, defs)
			if (raw === undefined) return
			result[`[/${key.replaceAll("/", "\\/")}/]`] = raw
		}
	}

	const additionalProperties = schema.additionalProperties
	if (additionalProperties === false) result["+"] = "reject"
	else if (additionalProperties !== undefined && additionalProperties !== true) return

	return result
}

const rawArrayDef = (
	schema: JsonSchema.Array,
	defs: Record<string, JsonSchema>
): unknown => {
	if ("uniqueItems" in schema || "contains" in schema) return

	if ("items" in schema && !Array.isArray(schema.items)) {
		const raw = jsonSchemaToRawDef(schema.items as JsonSchema, defs)
		if (raw === undefined) return
		if (typeof raw !== "string") return
		let def = `${raw}[]`
		if ("minItems" in schema) def += ` >= ${schema.minItems}`
		if ("maxItems" in schema) def += ` <= ${schema.maxItems}`
		return def
	}

	if ("prefixItems" in schema || Array.isArray(schema.items)) {
		const prefix = Array.isArray(schema.items)
			? schema.items
			: (schema.prefixItems ?? [])
		const rawPrefix = prefix.map(item => jsonSchemaToRawDef(item, defs))
		if (rawPrefix.some(raw => raw === undefined)) return
		if (
			"minItems" in schema ||
			"maxItems" in schema ||
			"additionalItems" in schema
		)
			return
		return rawPrefix
	}

	let def = "unknown[]"
	if ("minItems" in schema) def += ` >= ${schema.minItems}`
	if ("maxItems" in schema) def += ` <= ${schema.maxItems}`
	return def
}

const rawUnionOrIntersection = (
	branches: readonly JsonSchema[],
	defs: Record<string, JsonSchema>,
	operator: "|" | "&"
): unknown => {
	const rawBranches = branches.map(branch => jsonSchemaToRawDef(branch, defs))
	if (rawBranches.some(raw => raw === undefined)) return
	const result: unknown[] = []
	rawBranches.forEach((branch, index) => {
		if (index > 0) result.push(operator)
		result.push(branch)
	})
	return result
}

/**
 * Convert a JSON Schema into a raw ArkType definition that can be placed
 * directly in a scope so that recursive $defs resolve lazily.
 *
 * Returns `undefined` when the schema cannot be fully represented as a raw
 * definition (e.g. it needs predicates), in which case it is parsed eagerly.
 */
export const jsonSchemaToRawDef = (
	jsonSchema: JsonSchema,
	defs: Record<string, JsonSchema>
): unknown => {
	if (typeof jsonSchema === "boolean") return jsonSchema ? "unknown" : "never"

	if ("$ref" in jsonSchema) {
		const name = getRefName(jsonSchema.$ref)
		if (!(name in defs)) return
		return name
	}

	if ("const" in jsonSchema) {
		if (typeof jsonSchema.const !== "object" || jsonSchema.const === null)
			return typeof jsonSchema.const === "string"
				? `'${jsonSchema.const.replaceAll("'", "\\'")}'`
				: String(jsonSchema.const)
		return
	}

	if ("enum" in jsonSchema) return rawEnumDef(jsonSchema)

	if ("anyOf" in jsonSchema)
		return rawUnionOrIntersection(jsonSchema.anyOf, defs, "|")

	if ("allOf" in jsonSchema)
		return rawUnionOrIntersection(jsonSchema.allOf, defs, "&")

	if ("oneOf" in jsonSchema || "not" in jsonSchema) return

	if ("type" in jsonSchema) {
		if (Array.isArray(jsonSchema.type)) {
			const branches = jsonSchema.type.map(t =>
				jsonSchemaToRawDef({ ...jsonSchema, type: t }, defs)
			)
			if (branches.some(branch => branch === undefined)) return
			const result: unknown[] = []
			branches.forEach((branch, index) => {
				if (index > 0) result.push("|")
				result.push(branch)
			})
			return result
		}
		switch (jsonSchema.type) {
			case "string":
				return rawStringDef(jsonSchema as JsonSchema.String)
			case "number":
			case "integer":
				return rawNumberDef(jsonSchema as JsonSchema.Numeric)
			case "boolean":
			case "null":
				return jsonSchema.type
			case "object":
				return rawObjectDef(jsonSchema as JsonSchema.Object, defs)
			case "array":
				return rawArrayDef(jsonSchema as JsonSchema.Array, defs)
			default:
				return
		}
	}

	if (hasObjectKeywords(jsonSchema))
		return rawObjectDef(jsonSchema as JsonSchema.Object, defs)

	return
}
