import { throwParseError } from "@ark/util"
import { type JsonSchema, type Type } from "arktype"
import { deepEqual } from "./deep.ts"
import type { JsonSchemaParseContext } from "./context.ts"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"

const deepUnitValidator = (value: unknown, ctx: JsonSchemaParseContext): Type => {
	const validator = (data: unknown) => deepEqual(data, value)
	return ctx.$.type("unknown").narrow(validator as never) as never
}

const deepEnumValidator = (
	values: readonly unknown[],
	ctx: JsonSchemaParseContext
): Type => {
	const validator = (data: unknown) => values.some(value => deepEqual(data, value))
	return ctx.$.type("unknown").narrow(validator as never) as never
}

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		const { const: value } = jsonSchema
		if (typeof value !== "object" || value === null) return ctx.$.unit(value)
		return deepUnitValidator(value, ctx)
	}

	if ("enum" in jsonSchema) {
		const values = jsonSchema.enum
		if (values.every(value => typeof value !== "object" || value === null))
			return ctx.$.enumerated(...values)
		return deepEnumValidator(values, ctx)
	}
}
