import {
	describeBranches,
	type JsonSchemaOrBoolean,
	type Traversal
} from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { scope, type, type JsonSchema, type Type } from "arktype"
import { parseArrayJsonSchema } from "./array.ts"
import { parseCommonJsonSchema } from "./common.ts"
import {
	parseAnyOfJsonSchema,
	parseCompositionJsonSchema
} from "./composition.ts"
import type { JsonSchemaParseContext } from "./context.ts"
import {
	writeJsonSchemaInsufficientKeysMessage,
	writeJsonSchemaUnsupportedTypeMessage
} from "./errors.ts"
import { parseNumberJsonSchema } from "./number.ts"
import { parseObjectJsonSchema } from "./object.ts"
import { JsonSchemaScope } from "./scope.ts"
import { parseStringJsonSchema } from "./string.ts"
import { getRefName, hasObjectKeywords, jsonSchemaToRawDef } from "./raw.ts"

const parseRef = (
	ref: string,
	ctx: JsonSchemaParseContext
): Type => {
	const name = getRefName(ref)
	if (!(name in ctx.defs))
		throwParseError(`Unable to resolve $ref "${ref}" from root $defs`)

	const cached = ctx.resolvedRefs.get(name)
	if (cached) return cached

	if (ctx.parsingDefs.has(name))
		throwParseError(
			`Unable to resolve recursive $ref "${ref}" within a non-structural schema`
		)

	const defSchema = ctx.defs[name]
	const rawDef = jsonSchemaToRawDef(defSchema, ctx.defs)

	if (rawDef !== undefined) {
		// The scope alias fully captures the def's semantics.
		const resolved = ctx.$.resolve(name)
		ctx.resolvedRefs.set(name, resolved)
		return resolved
	}

	// Non-structural def: parse eagerly.
	ctx.parsingDefs.add(name)
	const resolved = innerParseJsonSchema(defSchema, ctx)
	ctx.parsingDefs.delete(name)
	ctx.resolvedRefs.set(name, resolved)
	return resolved
}

const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	if (!("if" in jsonSchema)) return
	// if alone is a no-op
	if (!("then" in jsonSchema) && !("else" in jsonSchema)) return

	const ifValidator = innerParseJsonSchema(jsonSchema.if, ctx)
	const hasThen = "then" in jsonSchema
	const hasElse = "else" in jsonSchema
	const thenValidator = hasThen ?
		innerParseJsonSchema(jsonSchema.then as JsonSchema, ctx)
		: undefined
	const elseValidator = hasElse ?
		innerParseJsonSchema(jsonSchema.else as JsonSchema, ctx)
		: undefined

	const jsonSchemaConditionalValidator = (data: unknown, traversal: Traversal) => {
		if (ifValidator.allows(data)) {
			if (thenValidator === undefined) return true
			if (thenValidator.allows(data)) return true
			return traversal.reject({
				expected: `a value matching the 'then' schema of ${thenValidator.description}`,
				actual: printable(data)
			})
		}
		if (elseValidator === undefined) return true
		if (elseValidator.allows(data)) return true
		return traversal.reject({
			expected: `a value matching the 'else' schema of ${elseValidator.description}`,
			actual: printable(data)
		})
	}
	return ctx.$.type("unknown").narrow(jsonSchemaConditionalValidator)
}

const parseTypedJsonSchema = (
	jsonSchema: Extract<JsonSchema, { type?: unknown }>,
	ctx: JsonSchemaParseContext
): Type => {
	if (Array.isArray(jsonSchema.type)) {
		return parseAnyOfJsonSchema(
			jsonSchema.type.map(t => ({ type: t as never })),
			ctx
		)
	}

	switch (jsonSchema.type) {
		case "array":
			return parseArrayJsonSchema(jsonSchema as JsonSchema.Array, ctx)
		case "boolean":
		case "null":
			return ctx.$.type(jsonSchema.type)
		case "integer":
		case "number":
			return parseNumberJsonSchema(jsonSchema as JsonSchema.Numeric, ctx)
		case "object":
			return parseObjectJsonSchema(jsonSchema as JsonSchema.Object, ctx)
		case "string":
			return parseStringJsonSchema(jsonSchema as JsonSchema.String, ctx)
		default:
			throwParseError(
				writeJsonSchemaUnsupportedTypeMessage(printable(jsonSchema.type))
			)
	}
}

export const innerParseJsonSchema = (
	jsonSchema: JsonSchemaOrBoolean,
	ctx: JsonSchemaParseContext
): Type => {
	if (typeof jsonSchema === "boolean")
		return ctx.$.type(jsonSchema ? "unknown" : "never")

	if (Array.isArray(jsonSchema)) return parseAnyOfJsonSchema(jsonSchema, ctx)

	if ("$ref" in jsonSchema) {
		// $ref is the primary constraint; siblings are not combined for now.
		return parseRef(jsonSchema.$ref, ctx)
	}

	const constAndOrEnumValidator = parseCommonJsonSchema(
		jsonSchema as JsonSchema,
		ctx
	)
	const compositionValidator = parseCompositionJsonSchema(
		jsonSchema as JsonSchema,
		ctx
	)

	const preTypeValidator =
		constAndOrEnumValidator ?
			compositionValidator ? compositionValidator.and(constAndOrEnumValidator)
			:	constAndOrEnumValidator
		:	compositionValidator

	const conditionalValidator = parseConditionalJsonSchema(
		jsonSchema as JsonSchema,
		ctx
	)

	const combine = (validator: Type): Type =>
		conditionalValidator === undefined ? validator : validator.and(conditionalValidator)

	if ("type" in jsonSchema) {
		const typeValidator = parseTypedJsonSchema(jsonSchema, ctx)
		if (preTypeValidator === undefined) return combine(typeValidator)
		return combine(typeValidator.and(preTypeValidator))
	}

	if (hasObjectKeywords(jsonSchema as JsonSchema)) {
		const objectValidator = parseObjectJsonSchema(
			{ ...(jsonSchema as object), type: "object" } as JsonSchema.Object,
			ctx
		)
		if (preTypeValidator === undefined) return combine(objectValidator)
		return combine(objectValidator.and(preTypeValidator))
	}

	if (preTypeValidator === undefined && conditionalValidator === undefined) {
		const atLeastOneOf = [
			"'type'",
			"'enum'",
			"'const'",
			"'allOf'",
			"'anyOf'",
			"'oneOf'",
			"'not'",
			"'if'",
			"'$ref'"
		]
		throwParseError(
			writeJsonSchemaInsufficientKeysMessage(
				describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
				printable(jsonSchema)
			)
		)
	}
	if (preTypeValidator === undefined) return conditionalValidator!
	return combine(preTypeValidator)
}

const createJsonSchemaContext = (
	defs: Record<string, JsonSchema>
): JsonSchemaParseContext => {
	const rawDefs: Record<string, unknown> = {}
	for (const [name, def] of Object.entries(defs)) {
		const rawDef = jsonSchemaToRawDef(def, defs)
		rawDefs[name] = rawDef ?? "unknown"
	}

	// Use a dummy scope to satisfy the type; the real scope is created below.
	const $ = scope(rawDefs as never) as never

	return {
		$,
		defs,
		resolvedRefs: new Map(),
		parsingDefs: new Set()
	}
}

export const jsonSchemaToType = (
	jsonSchema: JsonSchemaOrBoolean
): type<unknown> => {
	if (typeof jsonSchema === "boolean")
		return type(jsonSchema ? "unknown" : "never") as never

	const rootSchema = jsonSchema as JsonSchema
	const defs: Record<string, JsonSchema> = rootSchema.$defs ?? {}

	const ctx = createJsonSchemaContext(defs)
	return innerParseJsonSchema(jsonSchema, ctx) as never
}
