const parseRef = (ref: string, ctx: JsonSchemaParseContext): Type => {
	const name = getRefName(ref)
	if (!(name in ctx.defs)) throwParseError(writeUnresolvableRefMessage(ref))

	const cached = ctx.resolvedRefs.get(name)
	if (cached) return cached

	if (ctx.parsingDefs.has(name)) {
		throwParseError(
			`Unable to resolve recursive $ref "${ref}" within a non-structural schema`
		)
	}

	const defSchema = ctx.defs[name]
	const rawDef = jsonSchemaToRawDef(defSchema, ctx.defs)

	if (rawDef !== undefined) {
		// The scope alias fully captures the def's semantics.
		const resolved = (ctx.$ as any).resolve(name)
		ctx.resolvedRefs.set(name, resolved)
		return resolved
	}

	// Non-structural def: parse eagerly.
	ctx.parsingDefs.add(name)
	const resolved = parseJsonSchema(defSchema, ctx)
	ctx.parsingDefs.delete(name)
	ctx.resolvedRefs.set(name, resolved)
	return resolved
}

const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	if (!("if" in jsonSchema)) {
		// then/else without if are no-ops
		if ("then" in jsonSchema || "else" in jsonSchema)
			return ctx.$.type("unknown")
		return
	}
	// if alone is a no-op
	if (!("then" in jsonSchema) && !("else" in jsonSchema))
		return ctx.$.type("unknown")

	const ifValidator = parseJsonSchema(jsonSchema.if, ctx)
	const hasThen = "then" in jsonSchema
	const hasElse = "else" in jsonSchema
	const thenValidator =
		hasThen ? parseJsonSchema(jsonSchema.then as JsonSchema, ctx) : undefined
	const elseValidator =
		hasElse ? parseJsonSchema(jsonSchema.else as JsonSchema, ctx) : undefined

	const jsonSchemaConditionalValidator = (
		data: unknown,
		traversal: Traversal
	) => {
		if (ifValidator.allows(data)) {
			if (thenValidator === undefined) return true
			if (thenValidator.allows(data)) return true
			return traversal.reject({
				expected: `a value matching the 'then' schema of ${thenValidator.description}`,
				actual: printable(data)
